/* Recuperação explícita, sem rede nem restauração automática ao abrir. */
(()=>{'use strict';const P=MartinsPersistenciaRdo;let busy=false;const dialog=document.createElement('dialog');dialog.id='mr-recovery';dialog.style.cssText='box-sizing:border-box;width:min(680px,calc(100vw - 20px));max-height:90vh;padding:22px;border:2px solid #b6954c;border-radius:12px';dialog.innerHTML='<h2 style="font-size:1.25rem;font-weight:bold">Conferir gravação local pendente</h2><p>Há um registro de salvamento em aberto. Se outra aba estiver salvando, aguarde. Se a operação foi interrompida, escolha uma recuperação. As versões da operação foram preservadas. Novas alterações nessas bases ficam bloqueadas até a recuperação.</p><p id="mr-recovery-info" role="status" style="white-space:pre-wrap;overflow-wrap:anywhere;margin:14px 0"></p><button id="mr-recovery-export" type="button">Baixar cópia da operação</button><button id="mr-recovery-login" type="button">Entrar com perfil autorizado</button><button id="mr-recovery-complete" type="button">Concluir gravação pendente</button><button id="mr-recovery-revert" type="button">Voltar ao estado anterior</button><p>A recuperação só aceita dados que ainda coincidam com as versões registradas. Alterações posteriores são preservadas e bloqueiam a recuperação automática.</p>';for(const b of dialog.querySelectorAll('button'))b.style.cssText='padding:10px;margin:6px;background:#765b28;color:white;border-radius:6px';document.body.append(dialog);const $=id=>document.getElementById(id);
function refresh(){if(!P.hasPending(localStorage))return;try{const op=P.pending(localStorage);$('mr-recovery-info').textContent='Operação: '+op.id+'\nSituação: '+op.status+'\nBases: '+op.records.map(x=>x.key==='cm_gestao_rdo_v5_db'?'RDO':x.key==='cm_frequencia_diaria_db'?'Frequência Diária':x.key==='cm_orcamentos_vendas_db_v1'?'Orçamentos e vendas':x.key==='cm_produtos_fator_db_v1'?'Catálogo de materiais':x.key==='cm_depositos_locais_v1'?'Depósitos':x.key==='cm_movimentos_depositos_v1'?'Movimentos entre depósitos':x.key==='cm_colaboradores_db'?'Colaboradores':x.key==='cm_documentos_colaboradores_v1'?'Documentos cadastrais':x.key==='cm_veiculos_v1'?'Veículos':x.key==='cm_abastecimentos_v1'?'Abastecimentos':x.key==='cm_contas_financeiras_v1'?'Contas financeiras':x.key==='cm_fluxo_caixa_obras_v1'?'Fluxo de caixa':'Gestão da Obra').join(', ')+(op.error?'\nFalha registrada: '+op.error:'');$('mr-recovery-complete').disabled=false;$('mr-recovery-revert').disabled=false;}catch(e){$('mr-recovery-info').textContent=e.message;$('mr-recovery-complete').disabled=true;$('mr-recovery-revert').disabled=true;}if(!dialog.open)dialog.showModal();}
dialog.addEventListener('cancel',event=>event.preventDefault());
$('mr-recovery-export').onclick=()=>{const raw=localStorage.getItem(P.KEY);if(raw===null)return;const url=URL.createObjectURL(new Blob([raw],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='martins_operacao_pendente_'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
for(const [button,mode] of [['mr-recovery-complete','concluir'],['mr-recovery-revert','reverter']])$(button).onclick=async()=>{try{let session;try{session=JSON.parse(sessionStorage.getItem('cm_active_user')||'null');}catch{}if(!currentLoggedUser||currentLoggedUser.status==='Inativo'||currentLoggedUser.perfil!=='Master'||!session||session.perfil!=='Master'||String(session.id||session.usuario||session.email)!==String(currentLoggedUser.id||currentLoggedUser.usuario||currentLoggedUser.email))throw Error('Entre com perfil Master autorizado para recuperar esta gravação local.');await P.withLock(navigator.locks,()=>P.recover(localStorage,mode,{actor:currentLoggedUser.nome||currentLoggedUser.usuario}));dialog.close();location.reload();}catch(e){$('mr-recovery-info').textContent=e.message;}};
$('mr-recovery-login').onclick=()=>{dialog.close();document.getElementById('btn-logout-header')?.click();};
document.getElementById('form-login-gate')?.addEventListener('submit',()=>setTimeout(()=>{if(P.hasPending(localStorage)&&document.getElementById('tela-login-gate')?.classList.contains('hidden'))refresh();},0));
window.martinsMostrarRecuperacao=refresh;
// Conflito de edição: mantém o formulário e oferece cópia antes de recarregar.
const conflict=document.createElement('section');conflict.id='mr-edit-conflict';conflict.hidden=true;conflict.style.cssText='padding:16px;border:2px solid #b45309;border-radius:10px;background:#fffbeb;color:#451a03;overflow-wrap:anywhere';conflict.innerHTML='<h3 style="font-weight:bold">Este RDO precisa de conferência</h3><p id="mr-edit-message" role="status" aria-live="polite"></p><p>O formulário continua com o seu preenchimento. Você pode baixar uma cópia para conferir as diferenças. Carregar a versão atual substitui este formulário somente após sua confirmação.</p><button id="mr-edit-export" type="button">Baixar meu preenchimento</button><button id="mr-edit-latest" type="button">Carregar versão atual</button>';for(const b of conflict.querySelectorAll('button'))b.style.cssText='padding:10px;margin:6px;border:1px solid #92400e;border-radius:6px;background:white';document.getElementById('form-rdo').prepend(conflict);
const confirmLatest=document.createElement('dialog');confirmLatest.id='mr-edit-confirm';confirmLatest.style.cssText='box-sizing:border-box;width:min(560px,calc(100vw - 20px));padding:22px;border:2px solid #92400e;border-radius:12px';confirmLatest.innerHTML='<h3 style="font-weight:bold">Substituir o preenchimento deste formulário?</h3><p>Baixe uma cópia se precisar guardar suas alterações. A versão atual será carregada do armazenamento local; isso não altera o RDO salvo nem envia dados.</p><button id="mr-edit-cancel" type="button">Voltar ao formulário</button><button id="mr-edit-reload" type="button">Substituir pela versão atual</button>';for(const b of confirmLatest.querySelectorAll('button'))b.style.cssText='padding:10px;margin:6px;border:1px solid #92400e;border-radius:6px;background:white';document.body.append(confirmLatest);
window.martinsLimparConflitoRdo=()=>{conflict.hidden=true;if(confirmLatest.open)confirmLatest.close();};
function editConflict(message){conflict.hidden=false;$('mr-edit-message').textContent=message;$('mr-edit-latest').disabled=false;}
$('mr-edit-export').onclick=()=>{try{const ids=['obra-select','input-data','input-rdo-num','clima-manha','prat-manha','clima-tarde','prat-tarde','textarea-servicos','textarea-equipamentos','textarea-materiais','textarea-ocorrencias','textarea-obs-gestao-interna','rdo-item-materiais','rdo-item-ocorrencias'];const fields=Object.fromEntries(ids.map(id=>[id,$(id)?.value??'']));const copy={format:'martins-edicao-rdo',version:1,exportedAt:new Date().toISOString(),base:window.martinsEdicaoRdoBase,fields,trabalhadores:structuredClone(currentTrabalhadores),fotos:structuredClone(currentFotos),servicosLista:structuredClone(window.currentServicosLista||[]),ocorrenciasFuncionarios:structuredClone(currentObsTrabalhadores)};const url=URL.createObjectURL(new Blob([JSON.stringify(copy,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='martins_preenchimento_rdo_'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){editConflict('Não foi possível baixar o preenchimento: '+e.message);}};
$('mr-edit-latest').onclick=()=>confirmLatest.showModal();$('mr-edit-cancel').onclick=()=>confirmLatest.close();
$('mr-edit-reload').onclick=()=>{try{P.guard(localStorage,'cm_gestao_rdo_v5_db');const docs=getDb(),id=window.currentEditingRdoId,found=docs.filter(x=>x.id===id);if(found.length!==1)throw Error('O RDO não está disponível com identificação única. Seu formulário foi preservado.');if(found[0].status==='Aprovado')throw Error('A versão atual está aprovada. Seu formulário foi preservado; confira o histórico e a reabertura autorizada.');window.carregarRdoParaEdicao(id);confirmLatest.close();showToast('Versão atual carregada. Confira o formulário antes de salvar.');}catch(e){confirmLatest.close();editConflict(e.message);}};
function checkEditor(){if(!window.currentEditingRdoId||!window.martinsEdicaoRdoBase)return;try{P.assertEdit(getDb(),window.martinsEdicaoRdoBase,window.currentEditingRdoId);}catch(e){editConflict(e.message);}}
window.addEventListener('storage',event=>{if(event.key==='cm_gestao_rdo_v5_db'||event.key===null)checkEditor();});
window.martinsAvisarConflitoRdo=editConflict;
const original=salvarRdo;salvarRdo=async function(status='Aprovado'){if(busy){showToast('Já há um salvamento em andamento nesta aba.','warning');return false;}busy=true;const beforeReceipt=window.martinsUltimaGravacaoRdo?.id;const buttons=[...document.querySelectorAll('#form-rdo button')].map(b=>({b,disabled:b.disabled}));buttons.forEach(x=>x.b.disabled=true);try{return await P.withLock(navigator.locks,()=>{P.guard(localStorage,'cm_gestao_rdo_v5_db');return original(status);});}catch(e){if(!P.hasPending(localStorage)&&window.martinsUltimaGravacaoRdo?.id!==beforeReceipt&&window.martinsUltimaGravacaoRdo?.status==='concluida'){showToast('RDO gravado; a atualização da tela falhou: '+e.message,'warning');return true;}if(e.code==='RDO_EDIT_CONFLICT')editConflict(e.message);showToast('RDO não confirmado: '+e.message,'warning');if(P.hasPending(localStorage))refresh();return false;}finally{buttons.forEach(x=>x.b.disabled=x.disabled);busy=false;}};
if(P.hasPending(localStorage))refresh();window.addEventListener('storage',event=>{if(event.key!==P.KEY)return;if(event.newValue===null){if(dialog.open)dialog.close();return;}setTimeout(()=>{if(P.hasPending(localStorage))refresh();},400);});
})();
